const upsertEventResult = `-- name: UpsertEventResult :exec
INSERT INTO event_results (event_id, submission_id, rank, score, confidence, published_at)
VALUES ($1, $2, $3, $4, $5, now())
ON CONFLICT (event_id, submission_id) DO UPDATE
SET rank = EXCLUDED.rank, score = EXCLUDED.score,
    confidence = EXCLUDED.confidence, published_at = now()
`

type UpsertEventResultParams struct {
	EventID      uuid.UUID `json:"event_id"`
	SubmissionID uuid.UUID `json:"submission_id"`
	Rank         int32     `json:"rank"`
	Score        float64   `json:"score"`
	Confidence   float64   `json:"confidence"`
}

func (q *Queries) UpsertEventResult(ctx context.Context, arg UpsertEventResultParams) error {
	_, err := q.db.Exec(ctx, upsertEventResult,
		arg.EventID,
		arg.SubmissionID,
		arg.Rank,
		arg.Score,
		arg.Confidence,
	)
	return err
}
